def fcoef_exact(P):
    cc,aa_,bb_,tt=P; w=dict(zip((c,a,b,t),[sp.Rational(x.numerator,x.denominator) for x in P]))
    sub={mm:m.subs(w),CC:C.subs(w),AA:A.subs(w),DD:D.subs(w),aa:al.subs(w)}
    ct=dict(u=cc,v=aa_*cc,W=bb_/aa_,Y=cc*(bb_-aa_**2*tt)/aa_,Z=Fr(1)); ps=[ct['W'],ct['Y'],ct['Z']]; out={}
    for key,co in fc.items():
        val=sp.Rational(co.subs(sub)); val=Fr(int(val.p),int(val.q))
        out[key]=val*ct['u']**key[0]*ct['v']**key[1]*ps[key[2]]*ps[key[3]]
    return out
BLK=[[(0,2,0),(2,0,0),(2,2,0),(0,0,1),(0,2,1),(2,0,1),(2,2,1),(0,0,2),(0,2,2),(2,0,2)],     # (i,j) in units of 1/2 (exponents of u,v), amplitude l (0=W,1=Y,2=Z)
     [(2,1,0),(0,1,1),(2,1,1),(0,1,2)],[(1,2,0),(1,0,1),(1,2,1),(1,0,2)],[(1,1,0),(1,1,1),(1,1,2)]]
def rows_exact(fcx):
    rows={k:[co,[]] for k,co in fcx.items()}
    for bi,bk in enumerate(BLK):
        n=len(bk)
        for r in range(n):
            for c_ in range(r,n):
                (i,j,l),(i2,j2,l2)=bk[r],bk[c_]; assert (i+i2)%2==0 and (j+j2)%2==0
                rows.setdefault(((i+i2)//2,(j+j2)//2,min(l,l2),max(l,l2)),[Fr(0),[]])[1].append((bi,r,c_))
    return rows
def vcoef(n,r,p): return (Fr(1) if r==p else Fr(0)) if r<n-1 else Fr(-1)   # G = V G' V^T, V = [I; -1^T] (rows r<n-1: e_r, last row: -1), so G*1 = 0 exactly
def exact_point(rec):
    P=tuple(Fr(x) for x in rec['pt']); cc,aa_,bb_,tt=P; zz_=cc*cc; hh_=bb_-aa_**2*tt
    assert 0<tt<1 and cc>0 and aa_>0 and hh_>0 and (1+zz_)*bb_-(1+aa_**2*zz_*tt)>0 and 1-zz_*hh_>0     # in Phi
    fcx=fcoef_exact(P); rows=rows_exact(fcx)
    ms=[len(bk)-1 for bk in BLK]; offs=[0]
    for mq in ms: offs.append(offs[-1]+mq*(mq+1)//2)
    idx=lambda bi,p,q: offs[bi]+max(p,q)*(max(p,q)+1)//2+min(p,q)
    keys=sorted(rows); rowsA=[]; rhs=[rows[k][0] for k in keys]
    for k in keys:
        co,ent=rows[k]; d={}
        for (bi,r,c_) in ent:
            n=len(BLK[bi]); mult=1 if r==c_ else 2
            for p in range(n-1):
                x=vcoef(n,r,p)
                if x==0: continue
                for q in range(n-1):
                    y=vcoef(n,c_,q)
                    if y==0: continue
                    ii=idx(bi,p,q); d[ii]=d.get(ii,0)+mult*x*y     # ordered pair (p,q): G'[p,q] and G'[q,p] share the unknown, each visited once
        rowsA.append(d)
    x0=[Fr(0)]*offs[-1]
    for bi,G in enumerate(rec['Gp']):
        for p in range(ms[bi]):
            for q in range(p+1): x0[idx(bi,p,q)]=Fr(G[p][q])        # float string -> exact rational
    res=[rhs[i]-sum(v_*x0[j] for j,v_ in rowsA[i].items()) for i in range(len(keys))]
    ncol=offs[-1]; rowsE=[(dict(rowsA[i]),res[i]) for i in range(len(keys))]; used=set(); pivrows=[]
    for col in range(ncol):                                         # exact Gauss-Jordan: correction delta supported on pivot columns
        pr=None
        for ri,(rw,rr) in enumerate(rowsE):
            if ri in used: continue
            if rw.get(col,0)!=0: pr=ri; break
        if pr is None: continue
        used.add(pr); rw,rr=rowsE[pr]; pv=rw[col]; rw={k_:v_/pv for k_,v_ in rw.items()}; rr=rr/pv; rowsE[pr]=(rw,rr)
        for ri,(rw2,rr2) in enumerate(rowsE):
            if ri==pr: continue
            f=rw2.get(col,0)
            if f!=0:
                nr=dict(rw2)
                for k2,v2 in rw.items():
                    nv=nr.get(k2,0)-f*v2
                    if nv==0: nr.pop(k2,None)
                    else: nr[k2]=nv
                rowsE[ri]=(nr,rr2-f*rr)
        pivrows.append((col,pr))
    for ri,(rw,rr) in enumerate(rowsE):
        if ri not in used: assert rr==0 and not rw, 'inconsistent system'
    delta=[Fr(0)]*ncol
    for col,pr in pivrows: delta[col]=rowsE[pr][1]
    x=[x0[j]+delta[j] for j in range(ncol)]
    for i in range(len(keys)): assert sum(v_*x[j] for j,v_ in rowsA[i].items())==rhs[i]       # ALL coefficient equations EXACT
    maxd=max(abs(d_) for d_ in delta)
    mins=[]
    for bi in range(len(BLK)):                                     # exact LDL of reduced Gram blocks G'_b (kernel of G_b is exactly span(1)=contact in primed coordinates)
        mq=ms[bi]; Mx=[[x[idx(bi,p,q)] for q in range(mq)] for p in range(mq)]; Lp=[]
        for k in range(mq):
            pivot=Mx[k][k]; assert pivot>0, ('non-PD pivot',bi,k,float(pivot)); Lp.append(pivot)
            for i in range(k+1,mq):
                f=Mx[i][k]/pivot
                for j in range(k,mq): Mx[i][j]-=f*Mx[k][j]
        mins.append(float(min(Lp)))
    return len(keys),len(pivrows),float(maxd),mins
for rec in DATA:
    nk,rk,md,mins=exact_point(rec)
    say('PASS (E5): (c,a,b,t)=(%s): %d coefficient rows (rank %d) hold EXACTLY; exact-rational Gram blocks 10+4+4+3 (reduced %s) all PD by exact LDL, smallest pivots %s (max exact correction %.1e)'%(','.join(rec['pt']),nk,rk,[len(B)-1 for B in BLK],['%.2e'%x for x in mins],md))
say('ALL ASSERTIONS PASSED')
